import React from 'react';
import { AppBar, Toolbar, Button, Box, useTheme } from '@mui/material';
import { useAuth } from '../../contexts/AuthContext';
import LogoutIcon from '@mui/icons-material/Logout';
import DarkModeToggle from './DarkModeToggle';

const Header = () => {
  const { user, logout } = useAuth();
  const theme = useTheme();

  return (
    <AppBar 
      position="sticky" 
      sx={{ 
        background: theme.palette.mode === 'dark' 
          ? 'linear-gradient(90deg, #1e1e2f 0%, #2c2c44 100%)' 
          : 'linear-gradient(90deg, #1976d2 0%, #2196f3 100%)',
        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)'
      }}
    >
      <Toolbar sx={{ display: 'flex', justifyContent: 'space-between' }}>
        {/* Left empty to replace the title that was removed */}
        <Box />
        
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          {user && (
            <Box sx={{ display: 'flex', alignItems: 'center', mr: 2 }}>
              <Box 
                sx={{ 
                  backgroundColor: theme.palette.mode === 'dark' ? 'rgba(0, 255, 255, 0.2)' : 'rgba(255, 255, 255, 0.3)', 
                  px: 2, 
                  py: 0.5, 
                  borderRadius: 2,
                  fontSize: '0.9rem',
                  fontWeight: 'medium',
                  color: theme.palette.mode === 'dark' ? 'cyan' : 'white' 
                }}
              >
                {user.username}
              </Box>
              <Button 
                color="inherit" 
                onClick={logout}
                startIcon={<LogoutIcon />}
                size="small"
                sx={{ ml: 1 }}
              >
                Logout
              </Button>
            </Box>
          )}
          <DarkModeToggle />
        </Box>
      </Toolbar>
    </AppBar>
  );
};

export default Header;
